function drawFace(ctx, cx, cy, o, colors, t) {
  const eye = EYE_COLORS.find((e) => e.id === o.eyeColor)?.hex ?? '#e6b35c';
  const skin = colors.skin, skinShade = darken(skin, 0.22), skinLight = lighten(skin, 0.16);
