    ctx.beginPath(); ctx.moveTo(cx, bodyY + 72); ctx.lineTo(cx + 5, bodyY + 80); ctx.lineTo(cx, bodyY + 88); ctx.lineTo(cx - 5, bodyY + 80); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = rgba('#ffffff', 0.4); ctx.lineWidth = 0.8; ctx.stroke();
    // belt
