  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    ctx.beginPath(); ctx.moveTo(64 + Math.cos(a) * 18, 64 + Math.sin(a) * 18);
    ctx.quadraticCurveTo(64 + Math.cos(a) * 36, 64 + Math.sin(a) * 36, 64 + Math.cos(a + 0.4) * 50, 64 + Math.sin(a + 0.4) * 50);
    ctx.stroke();
