    resource: 0,
    zoneId: 'greendale',
    x: 0, y: 0,
    equipment: {},
    inventory: [],
    storage: [],
    stones: [],
    activeStone: null,
    quests: {},
    completedChapters: 0,
    discoveredZones: ['greendale'],
    visited: { greendale: true },
    kills: 0,
