    for (const m of this.monsters) {
      if (m.dead) continue;
      const d = dist(wx, wy, m.x, m.y - 26 * m.scale);
      const r = (m.boss ? 46 : 30) * m.scale;
      if (d < Math.max(hd, r)) { hd = d; hit = m; }
