200: export function addItem(player, item, opts = {}) {
201:   if (!item) return false;
202:   if (item.stack) {
203:     const existing = player.inventory.find((x) => x.kind === item.kind && x.id === item.id && x.qty < (x.stackLimit ?? item.stack ?? 20));
204:     if (existing && existing.qty + (item.qty ?? 1) <= (existing.stackLimit ?? 20)) {
205:       existing.qty += item.qty ?? 1;
206:       return true;
207:     }
208:     if (existing) {
209:       const room = (existing.stackLimit ?? 20) - existing.qty;
210:       const left = (item.qty ?? 1) - room;
211:       existing.qty += room;
212:       if (left > 0) return addItem(player, { ...item, qty: left }, opts);
213:       return true;
214:     }
215:   }
216:   if (player.inventory.length >= INVENTORY_SIZE) return false;
217:   player.inventory.push({ ...item, uid: item.uid ?? uid('it') });
218:   return true;
219: }
