321: export function fuseItem(player, item) {
322:   if (!item || item.kind !== 'equip') return null;
323:   const key = item.key;
324:   const matches = player.inventory.filter((x) => x.kind === 'equip' && x.key === key);
325:   if (matches.length < 4) return null;
326:   const group = { items: matches, sample: item, result: makeFusionResult(item) };
327:   return fuseGroup(player, group);
328: }
