993:       const d = dist(pr.x, pr.y, pr.tx, pr.ty);
994:       if (d < 16) { pr.onHit?.(); pr.done = true; continue; }
995:       const a = Math.atan2(pr.ty - pr.y, pr.tx - pr.x);
996:       pr.x += Math.cos(a) * pr.speed * dt;
997:       pr.y += Math.sin(a) * pr.speed * dt;
998:       pr.life -= dt;
999:       this.addEffect({ kind: 'spark', x: pr.x, y: pr.y, color: pr.color, life: 0.25, maxLife: 0.25 });
1000:       if (pr.life <= 0) pr.done = true;
1001:     }
1002:     this.projectiles = this.projectiles.filter((p) => !p.done);
1003:   }
