.setting-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 11px;border-bottom:1px solid rgba(255,255,255,.04);min-height:44px;}
.setting-row:last-child{border-bottom:0;}
.setting-row .sr-label{font-size:10px;color:#cfc5b2;line-height:1.25;}
.setting-row .sr-hint{font-size:7.5px;color:#766f64;line-height:1.35;margin-top:2px;max-width:210px;}
.setting-row .sr-control{flex:none;display:flex;gap:4px;align-items:center;}
.seg{display:flex;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.25);}
.seg button{height:26px;padding:0 8px;font-size:8px;letter-spacing:.05em;color:#888175;}
.seg button.on{background:rgba(217,183,106,.16);color:#f3e5c6;}
.toggle{width:38px;height:21px;border-radius:11px;border:1px solid rgba(255,255,255,.15);background:rgba(0,0,0,.4);position:relative;transition:background .18s,border-color .18s;}
.toggle::after{content:"";position:absolute;left:2px;top:2px;width:15px;height:15px;border-radius:50%;background:#6f6a5e;transition:transform .18s,background .18s;}
.toggle.on{background:rgba(111,191,138,.15);border-color:rgba(111,191,138,.4);}
.toggle.on::after{transform:translateX(17px);background:#8fd8a6;}
.save-info{font-size:8.5px;line-height:1.7;color:#8d8578;}
.save-info b{color:#c8ba9f;font-weight:500;}
.settings-danger{border-color:rgba(201,86,79,.25);}
.settings-danger h3{color:#d98f88;}

/* dialogue */
.dialogue{position:fixed;left:0;right:0;bottom:0;z-index:75;padding:0 10px calc(10px + var(--safe-bottom));animation:dialogueIn .32s var(--ease) both;pointer-events:none;}
.dialogue-inner{max-width:500px;margin:0 auto;background:linear-gradient(165deg,rgba(28,25,30,.99),rgba(8,8,13,.995));border:1px solid rgba(217,183,106,.32);box-shadow:0 -15px 55px rgba(0,0,0,.7);position:relative;pointer-events:auto;}
.dialogue-inner::before{content:"";position:absolute;inset:4px;border:1px solid rgba(217,183,106,.075);pointer-events:none;}
.dialogue-head{display:flex;gap:10px;align-items:center;padding:13px 14px 9px;position:relative;}
.npc-portrait{width:48px;height:48px;border:1px solid rgba(217,183,106,.35);border-radius:50%;flex:none;background:radial-gradient(circle at 45% 35%,#4d4238,#16141a);display:grid;place-items:center;color:#d8c59d;position:relative;}
.npc-portrait svg{width:26px;height:26px;}
.dialogue-head h3{font-family:var(--font-display);font-size:15px;color:#f0dbb3;letter-spacing:.06em;}
.dialogue-head .npc-title{font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:#9a8f78;margin-top:2px;}
.dialogue-close{margin-left:auto;width:30px;height:30px;display:grid;place-items:center;color:#82796a;align-self:flex-start;}
.dialogue-close svg{width:16px;height:16px;}
.dialogue-text{padding:2px 16px 11px;font-size:10.5px;line-height:1.65;color:#c4baaa;font-style:italic;min-height:45px;}
.dialogue-actions{display:flex;gap:6px;flex-wrap:wrap;padding:0 14px 10px;}
.dialogue-actions .btn{min-height:33px;font-size:8px;padding:0 11px;flex:1;min-width:80px;}
.dialogue-quest{margin:0 14px 10px;padding:8px;border:1px solid rgba(217,183,106,.14);background:rgba(217,183,106,.035);font-size:8.5px;color:#a99b80;}
.dialogue-quest b{display:block;color:#d8c59d;font-family:var(--font-display);font-size:10px;margin-bottom:2px;}
@keyframes dialogueIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}

/* modal */
.modal-backdrop{z-index:95;}
.modal.item-modal{max-width:380px;}
.modal-head h3{font-size:14px;letter-spacing:.06em;}
.modal-body{padding:14px;}
.modal-foot .btn{flex:1;}
.item-modal-card{padding:0;border:0;background:transparent;}
.item-modal-card::before{display:none;}
.confirm-text{font-size:10.5px;line-height:1.65;color:#b5ab99;}
.confirm-text b{color:#e8d5ae;}
.credits-scroll{max-height:60vh;}
.credits-scroll h3{font-family:var(--font-display);font-size:14px;color:#e8d5ae;margin-bottom:8px;}
.credits-scroll p{font-size:9.5px;line-height:1.7;color:#968e7f;margin:0 0 10px;}
.credits-scroll .credit-line{display:flex;justify-content:space-between;gap:12px;font-size:9px;color:#847c6e;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.04);}
.credits-scroll .credit-line b{color:#bcaE92;font-weight:500;}

/* onboarding */
.onboarding{position:fixed;inset:0;z-index:100;background:radial-gradient(circle at 50% 35%,rgba(32,27,46,.8),rgba(3,3,6,.95));display:flex;align-items:center;justify-content:center;padding:22px;animation:fadeIn .35s both;}
.onboarding-card{width:100%;max-width:360px;border:1px solid rgba(217,183,106,.35);background:linear-gradient(165deg,rgba(25,23,31,.99),rgba(8,8,13,.995));padding:22px 18px 16px;position:relative;box-shadow:0 30px 80px rgba(0,0,0,.6);}
.onboarding-card::before{content:"";position:absolute;inset:5px;border:1px solid rgba(217,183,106,.07);pointer-events:none;}
.onboarding-icon{width:54px;height:54px;margin:0 auto 12px;border:1px solid rgba(217,183,106,.35);border-radius:50%;display:grid;place-items:center;color:var(--gold);background:radial-gradient(circle,rgba(217,183,106,.12),transparent);}
.onboarding-icon svg{width:28px;height:28px;}
.onboarding-card h2{font-family:var(--font-display);font-size:19px;text-align:center;color:#f2e3c2;letter-spacing:.05em;}
.onboarding-card p{font-size:10px;line-height:1.65;color:#a8a091;text-align:center;margin:8px 0 16px;min-height:48px;}
.onboarding-dots{display:flex;justify-content:center;gap:4px;margin-bottom:14px;}
.onboarding-dots i{width:5px;height:5px;border-radius:50%;background:#4b453c;}
.onboarding-dots i.on{background:var(--gold);}
.onboarding-actions{display:flex;gap:6px;}
.onboarding-actions .btn{flex:1;min-height:38px;font-size:9px;}

/* language */
.lang-compact{display:inline-flex;border:1px solid rgba(217,183,106,.25);background:rgba(5,6,10,.55);}
.lang-compact button{height:26px;padding:0 8px;font-size:8px;letter-spacing:.08em;color:#817a6e;}
.lang-compact button.on{color:#f2e2c0;background:rgba(217,183,106,.14);}

/* responsive */
@media(max-height:650px){
  .char-hero-wrap{height:236px;}
  .hud-bottom{height:200px;}
  .joystick{width:108px;height:108px;}
  .attack-cluster{width:142px;height:144px;}
  .attack-btn{width:68px;height:68px;}
  .skill-btn{width:43px;height:43px;}
  .skill-btn.s1{right:51px;bottom:86px}
  .skill-btn.s2{right:98px;bottom:52px}
  .skill-btn.s3{right:93px;bottom:1px}
  .quest-track{top:calc(95px + var(--safe-top));}
}
@media(min-width:720px){
  .panel{height:min(94%,900px);border-radius:5px 5px 0 0;}
}

/* ============ AETHERIA — full screens ============ */

/* ---------------- Main menu ---------------- */
.menu-screen{position:absolute;inset:0;overflow:hidden;background:
  radial-gradient(75% 55% at 50% 12%,rgba(52,40,77,.55),transparent 62%),
  radial-gradient(80% 70% at 50% 100%,rgba(37,48,34,.24),transparent 60%),
  linear-gradient(180deg,#0a0911,#07070b 40%,#030305);}
.menu-sky{position:absolute;inset:0;overflow:hidden;pointer-events:none;}
.menu-sky::before{content:"";position:absolute;left:50%;top:-120px;width:480px;height:480px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle,rgba(217,183,106,.09),transparent 62%);}
.menu-sky .star{position:absolute;width:1.5px;height:1.5px;border-radius:50%;background:rgba(240,232,208,.65);animation:starBlink 4s ease-in-out infinite;}
@keyframes starBlink{0%,100%{opacity:.18}50%{opacity:.8}}
.menu-ridge{position:absolute;left:0;right:0;bottom:0;height:45%;pointer-events:none;}
.menu-ridge svg{width:100%;height:100%;}
.menu-top{position:absolute;left:0;right:0;top:calc(14px + var(--safe-top));display:flex;justify-content:space-between;align-items:center;padding:0 18px;z-index:5;}
.menu-version{font-size:7.5px;letter-spacing:.16em;text-transform:uppercase;color:#5f5a50;}
.menu-brand{position:absolute;left:0;right:0;top:calc(55px + var(--safe-top));z-index:4;text-align:center;padding:0 16px;}
.menu-sigil{width:62px;height:62px;margin:0 auto 9px;opacity:.9;filter:drop-shadow(0 0 20px rgba(217,183,106,.3));}
.menu-brand h1{font-family:var(--font-display);font-size:clamp(32px,10vw,46px);letter-spacing:.34em;margin-left:.34em;background:linear-gradient(180deg,#fff3d1,#e3c27d 42%,#a07836 78%,#6f5124);-webkit-background-clip:text;background-clip:text;color:transparent;line-height:1;text-shadow:0 0 50px rgba(217,183,106,.15);}
.menu-brand .menu-sub{font-family:var(--font-display);font-size:8px;letter-spacing:.36em;text-transform:uppercase;color:#a29273;margin-top:9px;padding-left:.36em;}
.menu-brand .menu-rule{width:110px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,183,106,.55),transparent);margin:11px auto 0;position:relative;}
.menu-brand .menu-rule::after{content:"✦";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:7px;color:#d9b76a;background:#08080e;padding:0 5px;}
.menu-portrait{position:absolute;left:50%;top:calc(174px + var(--safe-top));transform:translateX(-50%);width:min(100%,430px);height:calc(100% - 430px);min-height:180px;pointer-events:none;z-index:1;opacity:.92;mask-image:linear-gradient(180deg,transparent 0,#000 16%,#000 72%,transparent 100%);-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 16%,#000 72%,transparent 100%);}
.menu-portrait canvas{width:100%;height:100%;object-fit:contain;}
.menu-portrait .portrait-haze{position:absolute;inset:0;background:radial-gradient(50% 60% at 50% 50%,transparent 30%,rgba(6,6,10,.22) 100%);}
.menu-actions{position:absolute;left:0;right:0;bottom:calc(24px + var(--safe-bottom));z-index:6;padding:0 26px;display:flex;flex-direction:column;gap:8px;}
.menu-actions .btn{height:52px;font-size:11px;letter-spacing:.19em;}
.menu-continue{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;height:58px!important;line-height:1.2;}
.menu-continue b{font-size:10px;letter-spacing:.2em;}
.menu-continue span{font-family:var(--font-ui);font-size:7.5px;letter-spacing:.09em;color:#b6a582;text-transform:none;margin-top:3px;max-width:90%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.menu-social{display:flex;justify-content:center;gap:8px;margin-top:2px;}
.menu-social button{font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#7f7769;padding:6px 9px;border:1px solid rgba(255,255,255,.07);display:flex;align-items:center;gap:5px;}
.menu-social svg{width:12px;height:12px;}
.menu-foot{position:absolute;left:0;right:0;bottom:calc(5px + var(--safe-bottom));z-index:3;text-align:center;font-size:6.5px;letter-spacing:.13em;text-transform:uppercase;color:#48443d;}
.menu-empty{text-align:center;padding:13px 10px;border:1px dashed rgba(217,183,106,.18);background:rgba(217,183,106,.022);margin-bottom:3px;}
.menu-empty p{font-size:8.5px;color:#777064;line-height:1.5;}
.menu-empty b{color:#bcae92;font-weight:500;}
.menu-notice{display:flex;align-items:center;gap:6px;justify-content:center;font-size:7.5px;color:#6b655a;letter-spacing:.03em;margin-top:2px;}
.menu-notice svg{width:11px;height:11px;color:#6d6657;}

/* ---------------- Character creation ---------------- */
.create-screen{position:absolute;inset:0;display:flex;flex-direction:column;background:
  radial-gradient(90% 55% at 50% 0,rgba(54,42,76,.38),transparent 62%),
  linear-gradient(180deg,#0b0a12,#07070c 50%,#040407);overflow:hidden;}
.create-head{flex:none;display:flex;align-items:center;gap:11px;padding:calc(13px + var(--safe-top)) 15px 10px;border-bottom:1px solid rgba(217,183,106,.12);background:rgba(8,8,13,.42);backdrop-filter:blur(8px);}
.create-head .back{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.12);color:#bdb19b;flex:none;}
.create-head .back svg{width:17px;height:17px;}
.create-head .ch-title{flex:1;min-width:0;}
.create-head h1{font-family:var(--font-display);font-size:16px;letter-spacing:.09em;color:#f0e3c8;}
.create-head p{font-size:7.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold-dim);margin-top:2px;}
.create-scroll{flex:1;min-height:0;overflow-y:auto;padding:14px 16px 30px;overscroll-behavior:contain;}
.create-preview{position:relative;height:255px;border:1px solid rgba(217,183,106,.2);background:radial-gradient(70% 66% at 50% 40%,rgba(50,42,69,.62),rgba(8,8,13,.92));overflow:hidden;margin-bottom:14px;}
.create-preview::before{content:"";position:absolute;left:50%;top:58%;width:240px;height:240px;transform:translate(-50%,-50%);border-radius:50%;border:1px dashed rgba(217,183,106,.12);}
.create-preview::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 55%,rgba(4,4,7,.82));pointer-events:none;}
#createHeroCanvas{width:100%;height:100%;display:block;}
.create-preview-meta{position:absolute;left:13px;right:13px;bottom:11px;z-index:2;display:flex;justify-content:space-between;align-items:flex-end;gap:8px;}
.create-preview-meta h2{font-family:var(--font-display);font-size:18px;color:#f2e5c9;letter-spacing:.05em;min-height:21px;}
.create-preview-meta p{font-size:8px;color:#a79778;letter-spacing:.1em;text-transform:uppercase;margin-top:2px;}
.create-preview-meta .cpm-badge{font-size:6.5px;letter-spacing:.11em;text-transform:uppercase;padding:3px 6px;border:1px solid rgba(217,183,106,.3);color:#d9c58f;background:rgba(8,8,13,.55);}
.create-step{display:flex;align-items:center;gap:7px;margin:18px 0 8px;}
.create-step .num{width:18px;height:18px;display:grid;place-items:center;border:1px solid rgba(217,183,106,.28);font-size:8px;color:#d9b76a;font-family:var(--font-display);flex:none;}
.create-step h3{font-family:var(--font-display);font-size:11px;letter-spacing:.11em;text-transform:uppercase;color:#dcd0b8;}
.create-step::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,rgba(217,183,106,.22),transparent);}
.faction-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.faction-card{position:relative;padding:13px 10px 11px;text-align:center;border:1px solid rgba(255,255,255,.08);background:linear-gradient(150deg,rgba(30,29,38,.7),rgba(9,9,14,.88));overflow:hidden;transition:border-color .18s,background .18s;}
.faction-card .fc-glyph{width:43px;height:43px;margin:0 auto 7px;border-radius:50%;display:grid;place-items:center;border:1px solid currentColor;opacity:.85;background:radial-gradient(circle,rgba(255,255,255,.06),transparent);}
.faction-card .fc-glyph svg{width:25px;height:25px;}
.faction-card.angel{color:#a9d5e5;}
.faction-card.demon{color:#e29289;}
.faction-card h4{font-family:var(--font-display);font-size:13px;letter-spacing:.08em;color:#eee1c7;margin:0 0 3px;}
.faction-card p{font-size:8px;line-height:1.45;color:#898176;min-height:35px;}
.faction-card .fc-bonus{font-size:7px;letter-spacing:.05em;color:#b2a37f;border-top:1px solid rgba(255,255,255,.06);padding-top:5px;margin-top:4px;}
.faction-card.on{border-color:currentColor;background:linear-gradient(150deg,rgba(59,58,76,.55),rgba(9,9,14,.9));box-shadow:inset 0 0 28px rgba(255,255,255,.025);}
.faction-card.on::after{content:"✓";position:absolute;right:6px;top:5px;font-size:8px;color:currentColor;}
.class-row{display:flex;flex-direction:column;gap:7px;}
.class-card{display:grid;grid-template-columns:48px 1fr auto;gap:10px;align-items:center;padding:10px;border:1px solid rgba(255,255,255,.075);background:linear-gradient(145deg,rgba(30,29,38,.65),rgba(9,9,14,.86));text-align:left;transition:border-color .18s;}
.class-card .cc-icon{width:48px;height:48px;border:1px solid rgba(217,183,106,.2);display:grid;place-items:center;color:var(--cc,#d9b76a);background:radial-gradient(circle at 40% 30%,rgba(255,255,255,.06),rgba(0,0,0,.25));}
.class-card .cc-icon svg{width:28px;height:28px;}
.class-card h4{font-family:var(--font-display);font-size:13px;color:#eaddc1;letter-spacing:.06em;}
.class-card .cc-role{font-size:7.5px;letter-spacing:.08em;text-transform:uppercase;color:#8f8573;margin-top:2px;}
.class-card .cc-desc{font-size:8.5px;line-height:1.45;color:#7d766b;margin-top:4px;}
.class-card .cc-check{width:18px;height:18px;border:1px solid rgba(255,255,255,.12);display:grid;place-items:center;color:transparent;font-size:9px;}
.class-card.on{border-color:rgba(217,183,106,.42);background:linear-gradient(145deg,rgba(57,48,33,.55),rgba(9,9,14,.9));}
.class-card.on .cc-check{border-color:rgba(217,183,106,.55);color:#f4df9a;background:rgba(217,183,106,.13);}
.seg-row{display:flex;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.22);margin-bottom:9px;}
.seg-row button{flex:1;height:34px;font-size:9px;letter-spacing:.07em;color:#8d8578;display:flex;align-items:center;justify-content:center;gap:5px;}
.seg-row button svg{width:13px;height:13px;}
.seg-row button.on{background:rgba(217,183,106,.13);color:#f0dfb9;}
.appearance-grid{display:flex;flex-direction:column;gap:9px;}
.field-label{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#8d8475;margin-bottom:4px;}
.field-label span{color:#6f685d;text-transform:none;letter-spacing:.02em;}
.wig-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;}
.wig-option{height:37px;border:1px solid rgba(255,255,255,.075);display:grid;place-items:center;color:#a79d89;background:rgba(255,255,255,.02);font-family:var(--font-display);font-size:11px;}
.wig-option.on{border-color:rgba(217,183,106,.5);color:#f1e0b8;background:rgba(217,183,106,.09);}
.swatches{display:flex;gap:5px;flex-wrap:wrap;}
.swatch-btn{width:26px;height:26px;border-radius:50%;border:2px solid rgba(255,255,255,.12);position:relative;}
.swatch-btn.on{border-color:#f4e3b0;box-shadow:0 0 0 2px rgba(244,227,176,.16);}
.outfit-row{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;}
.outfit-option{padding:6px 4px;border:1px solid rgba(255,255,255,.075);background:rgba(255,255,255,.02);text-align:center;}
.outfit-option .oo-swatch{display:flex;justify-content:center;gap:2px;margin-bottom:4px;}
.outfit-option .oo-swatch i{width:9px;height:9px;border-radius:50%;display:block;border:1px solid rgba(255,255,255,.15);}
.outfit-option span{font-size:7.5px;color:#9e9480;}
.outfit-option.on{border-color:rgba(217,183,106,.42);background:rgba(217,183,106,.065);}
.name-field{display:flex;gap:5px;}
.name-field input{flex:1;min-width:0;height:42px;padding:0 12px;background:rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.11);color:#f1e6d0;font-family:var(--font-display);font-size:14px;letter-spacing:.08em;}
.name-field input:focus{border-color:rgba(217,183,106,.42);}
.name-field .dice-btn{width:42px;height:42px;border:1px solid rgba(217,183,106,.25);display:grid;place-items:center;color:#baa77d;flex:none;background:rgba(0,0,0,.2);}
.name-field .dice-btn svg{width:18px;height:18px;}
.name-hint{font-size:7.5px;color:#6d665a;margin-top:4px;line-height:1.4;}
.create-foot{flex:none;padding:10px 16px calc(12px + var(--safe-bottom));border-top:1px solid rgba(217,183,106,.12);background:rgba(7,7,11,.9);backdrop-filter:blur(8px);}
.create-foot .btn{width:100%;height:49px;font-size:11px;}
.create-foot .foot-hint{text-align:center;font-size:7px;letter-spacing:.09em;text-transform:uppercase;color:#615b50;margin-top:6px;}
.name-error{min-height:14px;font-size:8.5px;color:#d8918a;margin-top:3px;}

/* ---------------- Game start / zone transition ---------------- */
.zone-intro{position:absolute;inset:0;z-index:50;background:radial-gradient(circle at 50% 45%,rgba(9,9,14,.5),rgba(3,3,5,.94));display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;animation:fadeIn .3s both;pointer-events:none;}
.zone-intro h2{font-family:var(--font-display);font-size:28px;letter-spacing:.16em;color:#f2e2bc;text-shadow:0 0 40px rgba(217,183,106,.25);animation:zoneIn 2.6s var(--ease) both;}
.zone-intro p{font-size:8px;letter-spacing:.24em;text-transform:uppercase;color:#b29a6b;margin-top:10px;}
@keyframes zoneIn{0%{opacity:0;transform:scale(.96);letter-spacing:.3em}25%,70%{opacity:1;transform:none;letter-spacing:.16em}100%{opacity:0;transform:translateY(-6px)}}

/* ---------------- Loading / generic ---------------- */
.boot.leaving{opacity:0;visibility:hidden;pointer-events:none;}
.boot{transition:opacity .7s var(--ease),visibility .7s;}

/* menu modal reuse */
.menu-screen .modal-backdrop{position:absolute;}

/* Landscape hint is deliberately non-blocking; the game works in both axes,
   but the HUD is tuned for portrait. */
@media(orientation:landscape) and (max-height:500px){
  .hud-bottom{height:170px;}
  .quest-track{top:calc(66px + var(--safe-top));width:min(52vw,230px);}
