.quest-card{padding:11px;border:1px solid rgba(255,255,255,.07);background:linear-gradient(145deg,rgba(27,26,33,.66),rgba(10,10,15,.82));margin-bottom:8px;position:relative;}
.quest-card.story{border-left:2px solid rgba(217,183,106,.75);}
