660:   usePotion() {
661:     if (this.player.hp >= this.player.stats.maxHp * 0.999) { this.notify(t('toast.potionFull')); return false; }
662:     const potion = this.player.inventory.find((i) => i.kind === 'consumable' && i.id === 'healPotion' && (i.qty ?? 0) > 0);
663:     if (!potion) { this.notify(t('common.empty'), 'bad'); return false; }
664:     const heal = this.player.stats.maxHp * 0.45;
665:     this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
666:     if ((potion.qty ?? 1) > 1) potion.qty--; else this.player.inventory.splice(this.player.inventory.indexOf(potion), 1);
667:     this.floater(this.player.x, this.player.y - 72, `+${Math.round(heal)}`, '#8ce07a', 1.1);
668:     this.addEffect({ kind: 'pillar', x: this.player.x, y: this.player.y, color: '#8ce07a', life: 0.7, maxLife: 0.7 });
669:     this.sfx('heal');
670:     this.save();
671:     return true;
672:   }
