722:   // ── monsters ────────────────────────────────────────────────────────────
723:   updateMonsters(dt) {
724:     const p = this.player;
725:     for (const m of this.monsters) {
726:       if (m.dead) {
727:         if (this.time >= m.respawnAt && this.time > 0) {
728:           m.dead = false; m.hp = m.maxHp; m.x = m.homeX; m.y = m.homeY; m.aggro = false; m.state = 'idle'; m.stunUntil = 0; m.slowUntil = 0; m.poisonUntil = 0; m.burnUntil = 0;
729:         }
730:         continue;
731:       }
732:       m.anim += dt;
733:       m.flash = Math.max(0, m.flash - dt);
734:       // status effects
735:       if (m.poisonUntil > this.time) {
736:         m.poisonTick += dt;
737:         if (m.poisonTick >= 1) {
738:           m.poisonTick = 0;
739:           const dmg = Math.max(1, Math.round(this.player.stats.attack * 0.16));
740:           m.hp -= dmg;
741:           this.floater(m.x, m.y - 60, `${dmg}`, '#8ce07a', 0.9);
742:           if (m.hp <= 0) { this.killMonster(m); continue; }
743:         }
744:       }
745:       if (m.burnUntil > this.time) {
746:         m.burnTick += dt;
747:         if (m.burnTick >= 0.8) {
748:           m.burnTick = 0;
749:           const dmg = Math.max(1, Math.round(this.player.stats.attack * 0.12));
750:           m.hp -= dmg;
751:           this.floater(m.x, m.y - 58, `${dmg}`, '#ff9a5c', 0.9);
752:           if (m.hp <= 0) { this.killMonster(m); continue; }
753:         }
754:       }
755:       if (m.stunUntil > this.time) continue;
756:       const dToPlayer = dist(m.x, m.y, p.x, p.y);
757:       const aggroRange = m.boss ? 360 : m.elite ? 270 : 200;
758:       const leash = m.boss ? 460 : 500;
759:       if (this.dead) m.aggro = false;
760:       if (!m.aggro && dToPlayer < aggroRange && !this.dead) {
761:         m.aggro = true;
762:         if (m.boss && !this.bossWarned) {
763:           this.bossWarned = true;
764:           this.bossEngaged = true;
765:           this.notify(t('combat.bossWarning', { name: tx(m.name) }), 'bad');
766:           this.sfx('boss');
767:         } else if (m.elite) {
768:           this.notify(t('combat.eliteWarning'), 'bad');
769:         }
770:       }
771:       const homeDist = dist(m.x, m.y, m.homeX, m.homeY);
772:       if (m.aggro && homeDist > leash) {
773:         m.aggro = false;
774:         m.state = 'return';
775:       }
776:       const slowMul = m.slowUntil > this.time ? 0.45 : 1;
777:       const baseSpeed = m.boss ? 68 : m.elite ? 86 : 78;
778:       const speed = baseSpeed * slowMul * (m.boss ? 1 : m.scale * 0.9);
779:       if (m.aggro) {
780:         const range = (m.boss ? 78 : 46) + m.scale * 6;
781:         if (dToPlayer > range) {
782:           const a = Math.atan2(p.y - m.y, p.x - m.x);
783:           let nx = m.x + Math.cos(a) * speed * dt;
784:           let ny = m.y + Math.sin(a) * speed * dt;
785:           // avoid stacking
786:           const r = resolveCollision(nx, ny, this.data.props);
787:           m.x = r.x; m.y = r.y;
788:           m.facing = p.x >= m.x ? 1 : -1;
789:           m.state = 'chase';
790:         } else {
791:           m.state = 'attack';
792:           m.attackCd -= dt;
793:           if (m.attackCd <= 0) {
794:             m.attackCd = m.boss ? 1.35 : m.elite ? 1.5 : 1.7;
795:             const dmg = m.attack * (0.9 + Math.random() * 0.2) * (m.boss ? 1.15 : 1);
796:             this.damagePlayer(dmg, m);
797:             this.addEffect({ kind: 'enemySlash', x: m.x, y: m.y - 30, tx: p.x, ty: p.y - 30, color: '#ff8a6a', life: 0.28, maxLife: 0.28 });
798:             this.sfx('enemy');
799:           }
800:         }
801:         if (m.boss) this.updateBoss(dt, m);
802:       } else if (m.state === 'return' && homeDist > 30) {
803:         const a = Math.atan2(m.homeY - m.y, m.homeX - m.x);
804:         m.x += Math.cos(a) * speed * 1.2 * dt;
805:         m.y += Math.sin(a) * speed * 1.2 * dt;
806:         if (homeDist < 40) { m.state = 'idle'; m.hp = Math.min(m.maxHp, m.hp + m.maxHp * 0.3); }
807:       } else {
808:         // wander
809:         m.wanderTimer -= dt;
810:         if (m.wanderTimer <= 0) { m.wanderTimer = 2 + Math.random() * 4; m.wanderAngle = Math.random() * TAU; }
811:         if (Math.random() < 0.5) {
812:           const nx = m.x + Math.cos(m.wanderAngle) * 16 * dt;
813:           const ny = m.y + Math.sin(m.wanderAngle) * 16 * dt;
814:           if (dist(nx, ny, m.homeX, m.homeY) < 120) { const r = resolveCollision(nx, ny, this.data.props); m.x = r.x; m.y = r.y; }
815:           m.facing = Math.cos(m.wanderAngle) >= 0 ? 1 : -1;
816:         }
817:         m.state = 'idle';
818:       }
819:       if (!m.boss && m.aggro && dToPlayer < 300 && Math.random() < 0.02) {
820:         this.addEffect({ kind: 'aggro', x: m.x, y: m.y - 64, color: '#ff9a6a', life: 0.5, maxLife: 0.5 });
821:       }
822:       m.x = clamp(m.x, 40, WORLD_SIZE - 40);
823:       m.y = clamp(m.y, 40, WORLD_SIZE - 40);
824:     }
825:   }
