853:   updateLoot(dt) {
854:     const p = this.player;
855:     for (const l of this.loot) {
856:       if (l.collected) continue;
857:       l.born += dt;
858:       const d = dist(l.x, l.y, p.x, p.y);
859:       if ((l.type === 'gold' || l.type === 'gem') && d < 220) {
860:         const a = Math.atan2(p.y - l.y, p.x - l.x);
861:         const sp = 160 + (220 - d) * 1.6;
862:         l.x += Math.cos(a) * sp * dt;
863:         l.y += Math.sin(a) * sp * dt;
864:       }
865:       if (l.born > l.pickupDelay && d < 42) this.collectLoot(l);
866:     }
867:     this.loot = this.loot.filter((l) => !l.collected);
868:   }
