880:       this.sfx('gem');
881:     } else if (l.type === 'item') {
882:       if (addItem(p, l.item)) {
883:         this.notify(t('toast.loot', { item: this.itemLabel(l.item) }), 'good');
884:         this.sfx('loot');
885:       } else {
886:         const gold = sellValue(l.item);
887:         addGold(p, gold);
888:         this.notify(t('common.inventoryFull'), 'bad');
889:       }
890:     } else if (l.type === 'stone') {
891:       const stone = l.item;
892:       p.stones.push(stone);
893:       if (!p.activeStone) p.activeStone = stone.uid;
894:       recalc(p);
895:       this.notify(t('toast.bossStone', { name: tx(stone.name) }), 'good');
896:       this.sfx('stone');
897:     }
