992:   updateProjectiles(dt) {
993:     for (const pr of this.projectiles) {
994:       const d = dist(pr.x, pr.y, pr.tx, pr.ty);
995:       if (d < 16) { pr.onHit?.(); pr.done = true; continue; }
996:       const a = Math.atan2(pr.ty - pr.y, pr.tx - pr.x);
997:       pr.x += Math.cos(a) * pr.speed * dt;
998:       pr.y += Math.sin(a) * pr.speed * dt;
999:       pr.life -= dt;
1000:       this.addEffect({ kind: 'spark', x: pr.x, y: pr.y, color: pr.color, life: 0.25, maxLife: 0.25 });
1001:       if (pr.life <= 0) pr.done = true;
1002:     }
1003:     this.projectiles = this.projectiles.filter((p) => !p.done);
1004:   }
