8:     this.ws = null;
9:     this.url = null;
10:     this.state = 'offline';
11:     this.identity = null;
12:     this.players = [];
13:     this.handlers = new Map();
14:     this.queued = [];
15:   }
16: 
17:   on(event, fn) {
18:     if (!this.handlers.has(event)) this.handlers.set(event, new Set());
19:     this.handlers.get(event).add(fn);
20:     return () => this.handlers.get(event)?.delete(fn);
21:   }
22: 
23:   emit(event, payload) {
24:     for (const fn of this.handlers.get(event) ?? []) {
25:       try { fn(payload); } catch (error) { console.warn('TradeClient handler failed', error); }
26:     }
27:   }
