40:         reject(error);
41:         return;
42:       }
43:       this.ws = ws;
44:       const timeout = setTimeout(() => {
45:         if (this.state !== 'connecting') return;
46:         try { ws.close(); } catch {}
47:         this.state = 'offline';
48:         this.emit('state', { state: 'offline', error: 'Connection timed out.' });
49:         reject(new Error('Connection timed out.'));
50:       }, 7000);
51: 
52:       ws.addEventListener('open', () => {
53:         clearTimeout(timeout);
54:         this.state = 'online';
