102: .scroll{overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:rgba(217,183,106,.28) transparent;}
103: .scroll::-webkit-scrollbar{width:3px;}
104: .scroll::-webkit-scrollbar-thumb{background:rgba(217,183,106,.28);}
105: 
106: /* toasts */
107: .toast{pointer-events:none;min-width:190px;max-width:86%;padding:9px 16px;text-align:center;background:linear-gradient(180deg,rgba(28,25,20,.96),rgba(12,12,15,.97));border:1px solid rgba(217,183,106,.3);box-shadow:0 12px 34px rgba(0,0,0,.5);font-size:11.5px;letter-spacing:.04em;color:#eee4cd;animation:toastIn .3s var(--ease) both,toastOut .35s var(--ease) 2.6s both;}
108: .toast .t-gold{color:var(--gold);}
109: .toast.bad{border-color:rgba(201,86,79,.45);color:#f4b9b4;}
110: .toast.good{border-color:rgba(111,191,138,.4);color:#c2eed2;}
111: @keyframes toastIn{from{opacity:0;transform:translateY(-10px) scale(.97)}to{opacity:1;transform:none}}
112: @keyframes toastOut{to{opacity:0;transform:translateY(-6px)}}
113: 
114: /* common modal */
115: .modal-backdrop{position:absolute;inset:0;background:rgba(3,3,6,.7);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;padding:18px;animation:fadeIn .2s both;z-index:80;}
116: .modal{width:100%;max-width:420px;max-height:86%;overflow:hidden;display:flex;flex-direction:column;background:linear-gradient(160deg,rgba(24,23,30,.98),rgba(10,10,15,.99));border:1px solid rgba(217,183,106,.35);box-shadow:0 30px 80px rgba(0,0,0,.7);animation:modalIn .28s var(--ease) both;}
117: .modal-head{padding:16px 18px;border-bottom:1px solid rgba(217,183,106,.14);display:flex;justify-content:space-between;align-items:center;}
118: .modal-body{padding:16px 18px;overflow-y:auto;}
119: .modal-foot{padding:12px 18px calc(12px + var(--safe-bottom));border-top:1px solid rgba(255,255,255,.06);display:flex;gap:8px;}
120: @keyframes fadeIn{from{opacity:0}to{opacity:1}}
121: @keyframes modalIn{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:none}}
122: 
123: /* subclassing utility */
124: .row{display:flex;align-items:center;gap:10px;}
125: .col{display:flex;flex-direction:column;}
126: .spread{display:flex;align-items:center;justify-content:space-between;gap:10px;}
127: .grow{flex:1;min-width:0;}
128: .hidden{display:none!important;}
129: .pill{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 8px;border-radius:99px;background:rgba(0,0,0,.3);border:1px solid rgba(255,255,255,.08);font-size:10px;}
130: .center{display:flex;align-items:center;justify-content:center;}
