249: export function fusionResult(item) {
250:   if (!item || item.kind !== 'equip' || !item.fusable) return null;
251:   const ri = RARITY_ORDER.indexOf(item.rarity);
252:   if (ri < 0) return null;
253:   if (TiER_INVALID(item)) return null;
254:   if (item.tier === 'T3') return { rarity: item.rarity, tier: 'T2', level: item.level, classId: item.class, slot: item.slot };
255:   if (item.tier === 'T2') return { rarity: item.rarity, tier: 'T1', level: item.level, classId: item.class, slot: item.slot };
256:   if (item.tier === 'T1') {
257:     if (item.rarity === 'divine') return null;
258:     return { rarity: RARITY_ORDER[ri + 1], tier: 'T3', level: item.level, classId: item.class, slot: item.slot };
259:   }
260:   return null;
261: }
