167: function bagItems(p, filter) {
168:   if (filter === 'weapons' || filter === 'armor' || filter === 'jewelry') {
169:     const slots = SLOTS.filter((s) => s.group === filter).map((s) => s.id);
170:     return p.inventory.filter((it) => it.kind === 'equip' && slots.includes(it.slot));
171:   }
172:   if (filter === 'consumables') return p.inventory.filter((it) => it.kind === 'consumable');
173:   if (filter === 'materials') return p.inventory.filter((it) => it.kind === 'material');
174:   return p.inventory;
175: }
