const STONE_BONUS_POOL = [
  { stat: 'attack', min: 0.02, max: 0.06, pct: true },
  { stat: 'defense', min: 0.02, max: 0.06, pct: true },
  { stat: 'hp', min: 0.03, max: 0.08, pct: true },
