276:   const me = client?.identity?.id;
277:   const mine = msg.a?.id === me ? msg.a : msg.b;
278:   const theirs = msg.a?.id === me ? msg.b : msg.a;
279:   const p = panel.player;
280:   for (const item of mine?.items ?? []) removeItem(p, item, item.qty ?? 1);
281:   let stored = 0;
