303: export function attachTrade(panel) {
304:   const client = panel.screen.tradeClient;
305:   if (!client || panel._tradeOffs) return;
306:   panel._tradeOffs = [];
307:   const refresh = () => {
308:     if (panel.isOpen('trade') && !panel.tradePickerOpen) panel.refresh();
309:   };
310:   panel._tradeOffs.push(
311:     client.on('state', ({ state }) => {
312:       panel.tradeStatus = state;
313:       if (state !== 'online' && state !== 'connecting') {
314:         panel.tradeActive = null;
315:         panel.tradeOffer = [];
316:         panel.tradePlayers = [];
317:       }
318:       refresh();
319:     }),
320:     client.on('welcome', (msg) => {
321:       panel.tradeSelf = msg.you ?? null;
322:       refresh();
323:     }),
324:     client.on('presence', (msg) => {
325:       panel.tradePlayers = msg.players ?? [];
326:       refresh();
327:     }),
328:     client.on('trade:requested', (msg) => {
329:       toast(t('trade.invited', { name: msg.target?.name ?? '?' }), 'good');
330:     }),
331:     client.on('trade:invite', (msg) => {
332:       panel.tradeInvite = msg;
333:       toast(t('trade.incoming', { name: msg.from?.name ?? '?' }), 'good');
334:       refresh();
335:     }),
336:     client.on('trade:state', (msg) => {
337:       panel.tradeActive = msg.trade ?? null;
338:       const me = myTrader(panel, msg.trade);
339:       if (me?.offer) panel.tradeOffer = me.offer;
340:       panel.tradeInvite = null;
341:       refresh();
342:     }),
343:     client.on('trade:complete', (msg) => applyCompletion(panel, msg)),
344:     client.on('trade:cancel', () => {
345:       panel.tradeActive = null;
346:       panel.tradeOffer = [];
347:       toast(t('trade.cancelled'), 'bad');
348:       refresh();
349:     }),
350:     client.on('error', (msg) => {
351:       if (msg?.message) toast(String(msg.message), 'bad');
352:     }),
353:   );
354: }
