import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
page.setDefaultTimeout(15000);
const errors = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR ' + e.message); console.log('  ! ' + e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('CONSOLE ' + m.text()); console.log('  ! console: ' + m.text()); } });
page.on('response', (r) => { if (r.status() >= 400) { errors.push(`HTTP ${r.status()} ${r.url()}`); console.log(`  ! HTTP ${r.status()} ${r.url()}`); } });

const step = async (name, fn) => {
  try { await fn(); console.log('OK   ' + name); }
  catch (e) { console.log('FAIL ' + name + ' :: ' + e.message); errors.push('STEP ' + name + ' ' + e.message); }
};

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1500);

const heroName = 'TestHero';
await step('menu -> create', async () => {
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
});
await step('choose demon + mage + male', async () => {
  await page.locator('[data-faction="demon"]').click();
  await page.locator('[data-class="mage"]').click();
  await page.locator('[data-gender="male"]').click();
  await page.locator('#heroNameInput').fill(heroName);
});
await page.screenshot({ path: join(out, '01-create.png') });
await step('start game', async () => {
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
  await page.locator('#worldCanvas').waitFor({ timeout: 10000 });
  await page.waitForTimeout(1800);
});
await page.screenshot({ path: join(out, '02-world.png') });
await step('onboarding modal', async () => {
  if (await page.locator('[data-skip]').count()) {
    await page.screenshot({ path: join(out, '02b-onboarding.png') });
    await page.locator('[data-skip]').click();
    await page.waitForTimeout(300);
  }
});
await step('hud present', async () => {
  await page.locator('#hud').waitFor();
  const hp = await page.locator('#hud').innerText();
  if (!hp || hp.length < 5) throw new Error('HUD empty');
  console.log('     hud text: ' + hp.replace(/\s+/g, ' ').slice(0, 140));
});
await step('open menu drawer', async () => {
  await page.locator('[data-act="menu"]').click();
  await page.locator('.drawer').waitFor();
});
await page.screenshot({ path: join(out, '03-drawer.png') });

const panels = [['inventory', '04-inventory'], ['quests', '05-quests'], ['shop', '06-shop'], ['forge', '07-forge'], ['trade', '08-trade'], ['character', '09-character'], ['world', '11-world-panel'], ['mounts', '12-mounts'], ['storage', '13-storage'], ['wardrobe', '14-wardrobe']];
for (const [name, shot] of panels) {
  await step('panel ' + name, async () => {
    await page.locator(`[data-open="${name}"]`).click();
    await page.locator('.panel').waitFor();
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(out, `${shot}.png`) });
    await page.locator('[data-panel-close]').first().click();
    await page.waitForTimeout(200);
    await page.locator('[data-act="menu"]').click();
    await page.locator('.drawer').waitFor();
  });
}
await step('settings modal', async () => {
  await page.locator('[data-open="settings"]').click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(out, '15-settings.png') });
  await page.locator('[data-modal-close]').last().click();
  await page.waitForTimeout(200);
});
await step('language -> EN', async () => {
  await page.locator('[data-act="menu"]').click();
  await page.locator('[data-open="settings"]').click();
  await page.locator('[data-lang="en"]').click();
  await page.waitForTimeout(700);
  const menuText = await page.locator('#screen').innerText();
  if (!/CONTINUE|ENTER THE WORLD|NEW/i.test(menuText)) throw new Error('not english: ' + menuText.slice(0, 80));
  if ((await page.evaluate(() => localStorage.getItem('aetheria_settings_v1')))?.includes('"lang":"en"') !== true) {
    console.log('     settings raw: ' + (await page.evaluate(() => localStorage.getItem('aetheria_settings_v1'))));
  }
});
await page.screenshot({ path: join(out, '16-menu-en.png') });
await step('save exists', async () => {
  const keys = await page.evaluate(() => Object.keys(localStorage));
  console.log('     keys: ' + keys.join(','));
  if (!keys.some((k) => k.includes('save'))) throw new Error('no save key');
});
await step('reload -> continue', async () => {
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(1600);
  await page.locator('[data-menu-continue]').waitFor();
  await page.locator('[data-menu-continue]').click();
  await page.locator('#hud').waitFor();
  await page.waitForTimeout(1200);
});
await page.screenshot({ path: join(out, '17-reload-continue.png') });
await step('combat + movement', async () => {
  await page.locator('#attackBtn').click();
  await page.waitForTimeout(900);
  const before = await page.evaluate(() => window.AETHERIA.game.player.playtimeMs);
  if (typeof before !== 'number') throw new Error('playtime missing');
  await page.screenshot({ path: join(out, '18-combat.png') });
});
await step('open character panel via avatar', async () => {
  await page.locator('[data-act="character"]').click();
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(250);
  await page.screenshot({ path: join(out, '19-character-hud.png') });
  await page.locator('[data-panel-close]').first().click();
});

console.log('\nERRORS (' + errors.length + ')');
for (const e of errors) console.log(' - ' + e);
await browser.close();

