import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('pageerror', (e) => { console.log('PAGEERROR: ' + e.message); console.log(e.stack); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.locator('[data-menu-new]').click();
await page.locator('[data-create-start]').waitFor();
await page.locator('#heroNameInput').fill('DebugHero');
await page.locator('[data-create-start]').click();
await page.locator('[data-confirm-create]').click();
await page.waitForTimeout(2500);
const state = await page.evaluate(() => ({
  engine: Boolean(window.AETHERIA?.engine),
  running: window.AETHERIA?.engine?.running,
  zone: window.AETHERIA?.engine?.zoneId,
  draws: window.AETHERIA?.engine?.time,
  hud: Boolean(document.querySelector('.drawer')) || Boolean(document.querySelector('#hud')),
  onc: Boolean(document.querySelector('[data-skip]')),
}));
console.log(state);
await page.locator('[data-act="menu"]').click({ timeout: 5000 }).catch((e) => console.log('click err ' + e.message));
await page.waitForTimeout(800);
console.log('drawer?', await page.locator('.drawer').count());
await page.screenshot({ path: '/tmp/opencode/debug.png' });
await browser.close();

