/* ============ AETHERIA — shared game UI ============ */
:root{
  --panel-radius:3px;
}

/* ---------- screen / overlay helpers ---------- */
#screen{isolation:isolate;}
#overlay{isolation:isolate;}
.fade-in{animation:fadeIn .22s var(--ease) both;}
.slide-up{animation:slideUp .3s var(--ease) both;}
@keyframes slideUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}

/* ---------- HUD ---------- */
.game-screen{position:absolute;inset:0;background:#050508;overflow:hidden;}
#worldCanvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;}
.hud{position:absolute;inset:0;pointer-events:none;z-index:10;font-size:12px;}
.hud button,.hud input,.hud .tap{pointer-events:auto;}
.hud-top{position:absolute;top:0;left:0;right:0;padding:calc(8px + var(--safe-top)) 10px 0;display:flex;justify-content:space-between;align-items:flex-start;gap:8px;}
.hero-hud{display:flex;gap:8px;align-items:center;min-width:0;filter:drop-shadow(0 2px 5px rgba(0,0,0,.6));}
.hero-avatar{width:42px;height:42px;flex:none;border:1px solid rgba(217,183,106,.5);background:radial-gradient(circle at 40% 30%,rgba(64,55,38,.9),rgba(8,9,13,.95));display:grid;place-items:center;color:var(--gold-hi);position:relative;}
.hero-avatar::after{content:"";position:absolute;inset:3px;border:1px solid rgba(217,183,106,.15);}
.hero-avatar svg{width:23px;height:23px;}
.hero-hud-info{min-width:0;flex:1;}
.hero-name-line{display:flex;align-items:baseline;gap:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.hero-name-line b{font-family:var(--font-display);font-size:12px;letter-spacing:.05em;color:#f0e7d4;max-width:120px;overflow:hidden;text-overflow:ellipsis;}
.hero-name-line span{font-size:9px;color:var(--gold);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap;}
.bar{position:relative;height:8px;background:rgba(0,0,0,.66);border:1px solid rgba(255,255,255,.12);overflow:hidden;border-radius:1px;}
.bar>i{display:block;height:100%;transition:width .18s linear;}
.bar.hp>i{background:linear-gradient(90deg,#7d2c2b,#cf5147 55%,#e97d64);}
.bar.res>i{background:linear-gradient(90deg,#2f5a83,#579bd0 55%,#89d3ee);}
.bar.xp{height:4px;border-color:rgba(217,183,106,.18);background:rgba(0,0,0,.55);}
.bar.xp>i{background:linear-gradient(90deg,#8a6c36,#d9b76a,#f4e3b0);}
.hero-bars{display:flex;flex-direction:column;gap:3px;margin-top:3px;width:min(38vw,176px);}
.bar .bar-label{position:absolute;inset:0;display:flex;justify-content:space-between;padding:0 4px;font-size:7.5px;line-height:8px;font-weight:600;letter-spacing:.03em;color:rgba(255,255,255,.92);text-shadow:0 1px 2px #000;}
.hero-xp{margin-top:3px;width:min(38vw,176px);}
.top-right{display:flex;flex-direction:column;align-items:flex-end;gap:5px;}
.currency-row{display:flex;gap:5px;align-items:center;}
.currency{display:flex;align-items:center;gap:3px;height:23px;padding:0 7px;background:rgba(7,8,13,.72);border:1px solid rgba(217,183,106,.26);font-size:9.5px;font-weight:600;letter-spacing:.03em;color:#eadfc5;backdrop-filter:blur(5px);}
.currency svg{width:13px;height:13px;}
.currency.gold svg{color:#e8c26f;}
.currency.gems svg{color:#8fd8ee;}
.minimap-wrap{position:absolute;right:10px;top:calc(72px + var(--safe-top));width:92px;height:66px;border:1px solid rgba(217,183,106,.28);box-shadow:0 5px 18px rgba(0,0,0,.55);background:rgba(7,8,12,.6);overflow:hidden;}
