.minimap-wrap .zone-mini{position:absolute;left:0;right:0;bottom:0;padding:2px 4px;background:linear-gradient(transparent,rgba(4,5,8,.88));font-size:6.5px;color:#d7c7a2;text-transform:uppercase;letter-spacing:.11em;text-align:center;pointer-events:none;}
.zone-hud{position:absolute;left:50%;top:calc(9px + var(--safe-top));transform:translateX(-50%);font-family:var(--font-display);font-size:9px;letter-spacing:.19em;text-transform:uppercase;color:rgba(238,224,192,.76);text-shadow:0 2px 5px #000;white-space:nowrap;pointer-events:none;}
.zone-hud b{display:block;text-align:center;font-size:11px;letter-spacing:.14em;color:rgba(244,227,176,.95);}
.zone-hud .danger{display:block;text-align:center;font-family:var(--font-ui);font-size:7px;letter-spacing:.12em;color:#de9e70;margin-top:1px;}
.quest-track{position:absolute;left:10px;top:calc(106px + var(--safe-top));width:min(66vw,238px);padding:9px 10px 8px;background:linear-gradient(110deg,rgba(8,9,14,.82),rgba(8,9,14,.42) 75%,transparent);border-left:2px solid rgba(217,183,106,.55);pointer-events:auto;cursor:pointer;filter:drop-shadow(0 3px 8px rgba(0,0,0,.45));}
.quest-track .qt-eyebrow{font-size:7.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold);opacity:.9;}
.quest-track .qt-name{font-family:var(--font-display);font-size:12px;letter-spacing:.035em;color:#f1e7d1;margin-top:2px;line-height:1.25;text-shadow:0 1px 4px #000;}
.quest-track .qt-obj{display:flex;gap:6px;align-items:center;margin-top:4px;font-size:9.5px;color:#bdb5a5;line-height:1.25;}
.quest-track .qt-obj i{width:4px;height:4px;border-radius:50%;background:var(--gold-dim);flex:none;}
