    ctx.strokeStyle = 'rgba(255,220,170,.25)'; ctx.strokeRect(bx, by + 10, bw, 10);
    ctx.font = '600 11px Cinzel, Georgia, serif'; ctx.textAlign = 'center'; ctx.fillStyle = '#f0dfbd';
