import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('pageerror', (e) => console.log('PAGEERROR: ' + e.stack));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1000);
if (await page.locator('[data-menu-continue]').count()) {
  await page.locator('[data-menu-continue]').click();
} else {
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
  await page.locator('#heroNameInput').fill('LookHero');
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
}
await page.waitForTimeout(1500);
if (await page.locator('[data-skip]').count()) await page.locator('[data-skip]').click();
await page.waitForTimeout(4500);
const info = await page.evaluate(() => {
  const e = window.AETHERIA?.engine;
  const rects = [...document.querySelectorAll('#screen *')].filter((el) => {
    const cs = getComputedStyle(el); const r = el.getBoundingClientRect();
    return cs.display !== 'none' && cs.visibility !== 'hidden' && r.width > 40 && r.height > 3 && r.top > 480 && r.bottom < 760;
  }).map((el) => ({ tag: el.tagName, cls: el.className, r: [Math.round(el.getBoundingClientRect().x), Math.round(el.getBoundingClientRect().y), Math.round(el.getBoundingClientRect().width), Math.round(el.getBoundingClientRect().height)], txt: (el.textContent || '').slice(0, 40) }));
  return {
    interaction: e?.interaction, channel: e?.channel, dead: e?.dead, paused: e?.paused,
    status: document.getElementById('statusStrip')?.innerHTML,
    rects,
  };
});
console.log(JSON.stringify(info, null, 1));
await page.screenshot({ path: '/tmp/opencode/look.png' });
await browser.close();

