import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const root = '/home/runner/work/PlayGround/PlayGround';
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 512, height: 512 } });
const render = async (svgPath, size, out) => {
  const svg = readFileSync(join(root, svgPath), 'utf8');
  await page.setViewportSize({ width: size, height: size });
  await page.setContent(`<style>html,body{margin:0;background:#08080d}svg{width:100vw;height:100vh;display:block}</style>${svg}`, { waitUntil: 'load' });
  await page.screenshot({ path: join(root, out) });
  console.log(out);
};
await render('icons/icon.svg', 192, 'icons/icon-192.png');
await render('icons/icon.svg', 512, 'icons/icon-512.png');
await render('icons/icon.svg', 180, 'icons/apple-touch-icon.png');
await render('icons/icon.svg', 64, 'icons/favicon-64.png');
await render('icons/icon-maskable.svg', 512, 'icons/icon-maskable-512.png');
await browser.close();
writeFileSync('/tmp/opencode/icon-done', 'ok');

