  mon.aggro = false;
  this.player.kills = (this.player.kills ?? 0) + 1;
  if (mon.boss) {
    this.player.bossKills = (this.player.bossKills ?? 0) + 1;
    this.bossEngaged = false;
    this.bossWarned = false;
    this.bossSlamTimer = 4;
  }
  if (this.targetUid === mon.uid) this.targetUid = null;
