import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/tmp/opencode/func';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.setDefaultTimeout(12000);
const errors = [];
const log = (...a) => console.log(...a);
page.on('pageerror', (e) => { errors.push('PAGEERROR ' + e.message); log('  ! ' + e.stack); });
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('404') && !m.text().includes('bad HTTP')) { errors.push('CONSOLE ' + m.text()); log('  ! console: ' + m.text()); } });

const step = async (name, fn) => {
  try { await fn(); log('OK   ' + name); }
  catch (e) { log('FAIL ' + name + ' :: ' + e.message); errors.push('STEP ' + name + ' ' + e.message); }
};
const state = () => page.evaluate(() => window.AETHERIA.game.player);
const closePanel = async () => {
  if (await page.locator('[data-panel-close]').count()) await page.locator('[data-panel-close]').first().click();
  await page.waitForTimeout(150);
};
const openPanel = async (name) => {
  if (!(await page.locator('.drawer').count())) {
    await page.locator('[data-act="menu"]').click();
    await page.locator('.drawer').waitFor();
  }
  await page.locator(`[data-open="${name}"]`).click();
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(200);
};

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(1300);

await step('create hero', async () => {
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
  await page.locator('[data-faction="angel"]').click();
  await page.locator('[data-class="warrior"]').click();
  await page.locator('#heroNameInput').fill('FuncHero');
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
  await page.locator('#hud').waitFor();
  await page.waitForTimeout(900);
  if (await page.locator('[data-skip]').count()) await page.locator('[data-skip]').click();
  await page.waitForTimeout(600);
});

await step('starter kit', async () => {
  const p = await state();
  if (!p.equipment?.weapon) throw new Error('no starter weapon');
  if (p.inventory.length < 3) throw new Error('starter inventory too small: ' + p.inventory.length);
  if (p.level !== 1) throw new Error('not level 1');
  log('     inventory: ' + p.inventory.map((i) => i.kind + ':' + (i.id ?? i.key)).join(', '));
});

await step('gather a node', async () => {
  const result = await page.evaluate(() => {
    const e = window.AETHERIA.engine; const p = e.player;
    const n = e.nodes.find((x) => x.ready);
    p.x = n.x; p.y = n.y + 8;
    e.updateInteraction();
    const it = e.interaction;
    e.interact();
    e.finishGather(n);
    return { type: n.type, ready: n.ready, interaction: it?.kind, count: p.inventory.filter((i) => i.kind === 'material').length, gatherCount: p.gatherCount };
  });
  log('     gathered: ' + JSON.stringify(result));
  if (result.interaction !== 'node') throw new Error('node not detected');
  if (result.ready !== false) throw new Error('node still ready');
  if (!result.gatherCount) throw new Error('gather not counted');
});

await step('kill 10 wolves + loot', async () => {
  const result = await page.evaluate(() => {
    const e = window.AETHERIA.engine; const p = e.player;
    const wolves = e.monsters.filter((m) => m.defId === 'wolf' && !m.dead).slice(0, 10);
    for (const m of wolves) { p.x = m.x; p.y = m.y + 10; e.hitMonster(m, 999999); }
    const loot = e.loot.slice();
    for (const l of loot) e.collectLoot(l);
    const quest = p.quests ? Object.values(p.quests)[0] : null;
    return { killed: wolves.length, kills: p.kills, level: p.level, gold: p.gold, xp: p.xp, loot: loot.length, quest };
  });
  log('     combat: ' + JSON.stringify(result));
  if (result.killed < 10) throw new Error('not enough wolves');
  if (result.kills < 10) throw new Error('kills not counted');
});

await step('quest claim flow', async () => {
  const info = await page.evaluate(() => {
    const p = window.AETHERIA.game.player;
    return { quests: p.quests, done: p.questsDone, chapters: p.completedChapters };
  });
  log('     quest state: ' + JSON.stringify(info).slice(0, 240));
  await openPanel('quests');
  const claimable = await page.locator('[data-claim]').count();
  log('     claimable buttons: ' + claimable);
  if (claimable) {
    const before = await state();
    await page.locator('[data-claim]').first().click();
    await page.waitForTimeout(400);
    const after = await state();
    if (after.gold < before.gold && after.xp === before.xp) throw new Error('reward not applied');
    log('     claimed: gold ' + before.gold + ' -> ' + after.gold + ', xp ' + before.xp + ' -> ' + after.xp);
  }
  await closePanel();
});

await step('shop daily gift + mount purchase', async () => {
  await page.evaluate(() => { const p = window.AETHERIA.game.player; p.gems = 1000; });
  await openPanel('shop');
  const d = await page.locator('[data-daily]').count();
  if (d) {
    const before = (await state()).gems;
    await page.locator('[data-daily]').click();
    await page.waitForTimeout(300);
    const after = (await state()).gems;
    log('     daily gems: ' + before + ' -> ' + after);
    if (after < before) throw new Error('daily gift not granted');
  }
  await page.locator('[data-tab="mounts"]').click();
  await page.waitForTimeout(250);
  await page.locator('[data-buy-store="mount"]').first().click();
  await page.locator('[data-modal-close]').last().click().catch(() => {});
  const confirm = page.locator('[data-confirm]');
  if (await confirm.count()) await confirm.first().click();
  await page.waitForTimeout(400);
  const p = await state();
  log('     mounts: ' + JSON.stringify(p.mounts) + ' gems=' + p.gems);
  if (!p.mounts.includes('mount_wolf')) throw new Error('mount not purchased');
  const apply = page.locator('[data-apply-store="mount"]').first();
  if (await apply.count()) { await apply.click(); await page.waitForTimeout(300); }
  const mounted = (await state()).mount;
  log('     active mount: ' + mounted);
  if (!mounted) throw new Error('mount not equipped');
  await closePanel();
});

await step('merchant buy consumable', async () => {
  await page.evaluate(() => window.AETHERIA.openPanel('merchant'));
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(250);
  const btn = page.locator('[data-buy-cons]').first();
  const before = await state();
  await btn.click();
  await page.waitForTimeout(300);
  const after = await state();
  log('     gold: ' + before.gold + ' -> ' + after.gold + ', items: ' + before.inventory.length + ' -> ' + after.inventory.length);
  if (after.gold >= before.gold && after.inventory.length <= before.inventory.length) throw new Error('purchase failed');
  await closePanel();
});

await step('forge legendary craft', async () => {
  await page.evaluate(() => { const p = window.AETHERIA.game.player; p.gold = 9999; p.essence = 200; });
  await openPanel('forge');
  await page.locator('[data-tab="forge"]').click();
  await page.waitForTimeout(250);
  const before = (await state()).inventory.length;
  await page.locator('[data-craft-legendary]').click();
  await page.waitForTimeout(350);
  const p = await state();
  const legend = p.inventory.filter((i) => i.kind === 'equip' && i.rarity === 'legendary').length;
  log('     legendary items: ' + legend + ', essence=' + p.essence + ', inventory=' + before + ' -> ' + p.inventory.length);
  if (!legend) throw new Error('legendary craft failed');
  await closePanel();
});

await step('storage deposit/withdraw', async () => {
  await openPanel('inventory');
  await page.locator('[data-item-uid]').first().click();
  await page.locator('[data-item-act="storage"]').click();
  await page.waitForTimeout(300);
  let p = await state();
  log('     storage after deposit: ' + p.storage.length);
  if (!p.storage.length) throw new Error('deposit failed');
  await closePanel();
  await openPanel('storage');
  await page.locator('[data-item-uid]').first().click();
  await page.locator('[data-item-act="withdraw"]').click();
  await page.waitForTimeout(300);
  p = await state();
  log('     storage after withdraw: ' + p.storage.length + ', bag=' + p.inventory.length);
  await closePanel();
});

await step('death + respawn', async () => {
  await page.evaluate(() => window.AETHERIA.engine.damagePlayer(999999));
  await page.waitForTimeout(500);
  const veil = await page.locator('#deathVeil').isVisible();
  log('     death veil: ' + veil);
  if (!veil) throw new Error('death veil missing');
  await page.locator('[data-act="respawn"]').click();
  await page.waitForTimeout(500);
  const p = await state();
  if (p.hp <= 0) throw new Error('respawn did not restore hp');
  log('     respawn hp: ' + p.hp + '/' + p.stats.maxHp);
});

await step('travel to Ironcrag', async () => {
  await page.evaluate(() => { const p = window.AETHERIA.game.player; p.completedChapters = 2; p.gold = 9999; });
  const ok = await page.evaluate(() => window.AETHERIA.travel('ironcrag'));
  await page.waitForTimeout(900);
  const p = await state();
  log('     travel=' + ok + ' zone=' + p.zoneId + ' engineZone=' + (await page.evaluate(() => window.AETHERIA.engine.zoneId)));
  if (!ok || p.zoneId !== 'ironcrag') throw new Error('travel failed');
});

await step('language EN persists', async () => {
  await page.locator('[data-act="menu"]').click();
  await page.locator('[data-open="settings"]').click();
  await page.locator('[data-lang="en"]').click();
  await page.waitForTimeout(800);
  const saved = await page.evaluate(() => localStorage.getItem('aetheria_settings_v1'));
  const hud = await page.locator('#hud').innerText();
  log('     settings: ' + saved);
  if (!saved?.includes('en')) throw new Error('language not persisted');
  if (!/LEVEL|HP|MANA|RAGE/i.test(hud)) throw new Error('hud not in english');
});

await page.screenshot({ path: join(out, 'final-en.png') });
log('\nERRORS (' + errors.length + ')');
for (const e of errors) log(' - ' + e);
await browser.close();

