// Zero-dependency static server for local play and PWA install testing.
// Usage: npm start  (PORT=3000 by default)
import { createServer } from 'node:http';
import { createReadStream, statSync } from 'node:fs';
import { extname, join, normalize, resolve } from 'node:path';

const ROOT = resolve(process.cwd());
const PORT = Number(process.env.PORT ?? 3000);
const HOST = process.env.HOST ?? '0.0.0.0';

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
};

function safePath(urlPath) {
  const decoded = decodeURIComponent(urlPath.split('?')[0]);
  const normalized = normalize(decoded).replace(/^(\.\.[/\\])+/, '');
  return join(ROOT, normalized);
}

const server = createServer((req, res) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405, { allow: 'GET, HEAD' });
    res.end('Method not allowed');
    return;
  }
  let filePath = safePath(req.url ?? '/');
  try {
    if (statSync(filePath).isDirectory()) filePath = join(filePath, 'index.html');
  } catch {
    // Missing file: fall through to the SPA shell below.
    filePath = join(ROOT, 'index.html');
  }
  try {
    const stat = statSync(filePath);
    if (!stat.isFile()) throw new Error('not a file');
    const headers = {
      'content-type': MIME[extname(filePath).toLowerCase()] ?? 'application/octet-stream',
      'content-length': stat.size,
      'cache-control': filePath.endsWith('sw.js') ? 'no-cache' : 'no-cache',
    };
    res.writeHead(200, headers);
    if (req.method === 'HEAD') return res.end();
    createReadStream(filePath).pipe(res);
  } catch {
    res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
    res.end('Not found');
  }
});

server.listen(PORT, HOST, () => {
  console.log(`AETHERIA running at http://localhost:${PORT}/`);
  console.log('Install it from Chrome/Edge with "Install app" (PWA).');
});

// Copies the runtime web shell into www/ for Capacitor Android packaging.
// Usage: npm run build:web
import { cp, mkdir, readdir, rm, stat } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const out = join(root, 'www');

const ENTRIES = [
  'index.html',
  'manifest.webmanifest',
  'sw.js',
  'icons',
  'src',
];

async function main() {
  await rm(out, { recursive: true, force: true });
  await mkdir(out, { recursive: true });
  for (const entry of ENTRIES) {
    const from = join(root, entry);
    const to = join(out, entry);
    try {
      const info = await stat(from);
      if (info.isDirectory()) {
        await cp(from, to, { recursive: true });
      } else {
        await cp(from, to);
      }
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.warn(`skip missing ${entry}`);
        continue;
      }
      throw error;
    }
  }
  const files = await readdir(out);
  console.log(`Built www/ (${files.length} top-level entries) for Capacitor.`);
  console.log('Next: npx cap add android  (first time) or npm run android:sync');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

// End-to-end protocol test for server/server.mjs. Usage: npm run test:server
import { spawn } from 'node:child_process';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const port = Number(process.env.TEST_PORT ?? 8799);
const server = spawn(process.execPath, [join(root, 'server/server.mjs')], {
  env: { ...process.env, PORT: String(port), HOST: '127.0.0.1' },
  stdio: ['ignore', 'pipe', 'pipe'],
});
server.stdout.on('data', (d) => process.stdout.write('[server] ' + d));
server.stderr.on('data', (d) => process.stdout.write('[server:err] ' + d));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const waitFor = (fn, label, timeout = 5000) => new Promise((resolveFn, reject) => {
  const started = Date.now();
  const tick = () => {
    const value = fn();
    if (value) return resolveFn(value);
    if (Date.now() - started > timeout) return reject(new Error('timeout: ' + label));
    setTimeout(tick, 20);
  };
  tick();
});
const open = (c) => new Promise((resolveFn) => c.ws.addEventListener('open', resolveFn, { once: true }));

function makeClient(name, token) {
  const ws = new WebSocket(`ws://127.0.0.1:${port}`);
  const messages = [];
  const errors = [];
  ws.addEventListener('message', (e) => {
    const msg = JSON.parse(e.data);
    messages.push(msg);
    if (msg.type === 'error') errors.push(msg.message);
  });
  const send = (type, payload = {}) => ws.send(JSON.stringify({ type, ...payload }));
  const last = (type) => [...messages].reverse().find((m) => m.type === type);
  return { name, token, ws, messages, errors, send, last };
}

try {
  await sleep(400);
  const a = makeClient('Alpha', 'token-alpha');
  const b = makeClient('Beta', 'token-beta');
  await Promise.all([open(a), open(b)]);
  a.send('hello', { name: 'Alpha', classId: 'mage', level: 7, zoneId: 'ironcrag', token: 'token-alpha' });
  b.send('hello', { name: 'Beta', classId: 'warrior', level: 9, zoneId: 'greendale', token: 'token-beta' });

  const welcomeA = await waitFor(() => a.last('welcome'), 'welcome A');
  const welcomeB = await waitFor(() => b.last('welcome'), 'welcome B');
  if (welcomeA.you.name !== 'Alpha') throw new Error('name mismatch');

  const presence = await waitFor(() => {
    const p = a.last('presence');
    return p && p.players.length === 2 ? p : null;
  }, 'presence 2');
  console.log('presence:', presence.players.map((p) => `${p.name}/${p.level}/${p.zoneId}`).join(', '));

  a.send('trade:request', { targetId: welcomeB.you.id });
  const invite = await waitFor(() => b.last('trade:invite'), 'invite');
  if (invite.from.name !== 'Alpha') throw new Error('wrong inviter');

  b.send('trade:accept', { fromId: welcomeA.you.id });
  const stateA = await waitFor(() => a.last('trade:state'), 'state A');
  const tradeId = stateA.trade.id;
  await waitFor(() => b.last('trade:state'), 'state B');

  const itemA = { uid: 'eq_a1', kind: 'equip', name: 'Blade', rarity: 'epic', tradeable: true };
  const itemB = { uid: 'eq_b1', kind: 'equip', name: 'Shield', rarity: 'rare', tradeable: true };
  const wing = { uid: 'wing_bad', kind: 'wing', name: 'Forbidden', tradeable: false };
  a.send('trade:offer', { tradeId, items: [itemA, wing] });
  b.send('trade:offer', { tradeId, items: [itemB] });

  const synced = await waitFor(() => {
    const s = a.last('trade:state');
    return s?.trade.a.offer.length === 1 && s.trade.b.offer.length === 1 ? s : null;
  }, 'offers synced');
  if (synced.trade.a.offer[0].uid !== 'eq_a1') throw new Error('offer mismatch');
  console.log('offers synced; untradeable wing rejected:', synced.trade.a.offer.length === 1);

  a.send('trade:ready', { tradeId, ready: true });
  b.send('trade:ready', { tradeId, ready: true });
  await waitFor(() => a.last('trade:state')?.trade.a.ready && a.last('trade:state')?.trade.b.ready, 'both ready');

  a.send('trade:confirm', { tradeId });
  b.send('trade:confirm', { tradeId });
  const completeA = await waitFor(() => a.last('trade:complete'), 'complete A');
  const completeB = await waitFor(() => b.last('trade:complete'), 'complete B');
  if (completeA.trade.a.offer[0].uid !== 'eq_a1' || completeB.trade.b.offer[0].uid !== 'eq_b1') {
    throw new Error('completion payload mismatch');
  }
  console.log('trade completed for both players');

  a.send('trade:confirm', { tradeId });
  const guard = await waitFor(() => a.errors[0], 'post-complete guard');
  console.log('guard after completion:', guard);

  a.ws.close();
  const one = await waitFor(() => {
    const p = b.last('presence');
    return p && p.players.length === 1 ? p : null;
  }, 'presence 1');
  console.log('presence after disconnect:', one.players.length);

  console.log('\nALL SERVER CHECKS PASSED');
} catch (error) {
  console.error('SERVER TEST FAILED:', error.message);
  process.exitCode = 1;
} finally {
  server.kill('SIGTERM');
  await sleep(200);
}

import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/tmp/opencode/trade-shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);

const errors = [];
async function makePlayer(name, faction, classId) {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const page = await context.newPage();
  page.setDefaultTimeout(12000);
  page.on('pageerror', (e) => { errors.push(`[${name}] PAGEERROR ${e.message}`); console.log(`  ! [${name}] ${e.message}`); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('404') && !m.text().includes('bad HTTP')) { errors.push(`[${name}] ${m.text()}`); console.log(`  ! [${name}] ${m.text()}`); } });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(900);
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
  await page.locator(`[data-faction="${faction}"]`).click();
  await page.locator(`[data-class="${classId}"]`).click();
  await page.locator('#heroNameInput').fill(name);
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
  await page.locator('#hud').waitFor();
  await page.waitForTimeout(900);
  if (await page.locator('[data-skip]').count()) await page.locator('[data-skip]').click();
  await page.waitForTimeout(400);
  return { context, page };
}

const openTrade = async (page) => {
  if (!(await page.locator('.drawer').count())) {
    await page.locator('[data-act="menu"]').click();
    await page.locator('.drawer').waitFor();
  }
  await page.locator('[data-open="trade"]').click();
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(250);
};

const closePanel = async (page) => {
  if (await page.locator('[data-panel-close]').count()) await page.locator('[data-panel-close]').first().click();
  await page.waitForTimeout(150);
};

const state = (page) => page.evaluate(() => window.AETHERIA.game.player);

try {
  const A = await makePlayer('TraderA', 'angel', 'warrior');
  const B = await makePlayer('TraderB', 'demon', 'mage');

  await openTrade(A.page);
  await openTrade(B.page);
  await A.page.screenshot({ path: join(out, '01-offline.png') });

  console.log('connecting A/B...');
  await A.page.locator('[data-trade-connect]').click();
  await B.page.locator('[data-trade-connect]').click();
  await A.page.locator('.connection-status.online').waitFor({ timeout: 10000 });
  await B.page.locator('.connection-status.online').waitFor({ timeout: 10000 });
  await A.page.waitForTimeout(600);
  await B.page.waitForTimeout(600);
  console.log('connected; A sees B:', await A.page.locator('[data-trade-invite]').count(), 'B sees A:', await B.page.locator('[data-trade-invite]').count());
  await A.page.screenshot({ path: join(out, '02-online.png') });

  await A.page.locator('[data-trade-invite]').first().click();
  await B.page.locator('[data-trade-accept]').waitFor({ timeout: 6000 });
  await B.page.screenshot({ path: join(out, '03-invite.png') });
  await B.page.locator('[data-trade-accept]').click();
  await A.page.locator('[data-trade-add]').waitFor({ timeout: 6000 });
  await B.page.locator('[data-trade-add]').waitFor({ timeout: 6000 });
  console.log('trade session open on both sides');

  const addItem = async (page) => {
    await page.locator('[data-trade-add]').click();
    await page.locator('[data-pick-uid]').first().waitFor();
    const uid = await page.locator('[data-pick-uid]').first().getAttribute('data-pick-uid');
    await page.locator('[data-pick-uid]').first().click();
    await page.locator('[data-modal-close]').last().click();
    await page.waitForTimeout(400);
    return uid;
  };
  const uidA = await addItem(A.page);
  const uidB = await addItem(B.page);
  console.log('offered:', uidA, 'and', uidB);
  await A.page.screenshot({ path: join(out, '04-offers.png') });

  await A.page.locator('[data-trade-ready]').click();
  await B.page.locator('[data-trade-ready]').click();
  await A.page.waitForTimeout(500);
  const confirmA = A.page.locator('[data-trade-confirm]');
  const confirmB = B.page.locator('[data-trade-confirm]');
  console.log('confirm enabled:', await confirmA.isEnabled(), await confirmB.isEnabled());
  if (!(await confirmA.isEnabled()) || !(await confirmB.isEnabled())) throw new Error('confirm not enabled after ready');
  await confirmA.click();
  await confirmB.click();
  await A.page.waitForTimeout(900);
  await B.page.waitForTimeout(900);
  await A.page.screenshot({ path: join(out, '05-complete.png') });

  const afterA = await state(A.page);
  const afterB = await state(B.page);
  const aHasB = afterA.inventory.some((i) => i.uid === uidB);
  const bHasA = afterB.inventory.some((i) => i.uid === uidA);
  const aLostA = !afterA.inventory.some((i) => i.uid === uidA);
  const bLostB = !afterB.inventory.some((i) => i.uid === uidB);
  console.log('swap applied:', { aHasB, bHasA, aLostA, bLostB });
  if (!aHasB || !bHasA || !aLostA || !bLostB) throw new Error('inventory swap mismatch');

  await closePanel(A.page);
  await closePanel(B.page);
  const health = await (await fetch('http://localhost:8787/health')).json();
  console.log('server health after trade:', health);
  if (health.trades !== 0) throw new Error('trade not cleared on server');

  console.log('\nTRADE UI TEST PASSED');
  console.log('ERRORS (' + errors.length + ')');
  for (const e of errors) console.log(' - ' + e);
} catch (error) {
  console.error('TRADE UI TEST FAILED:', error.message);
  process.exitCode = 1;
  try {
    const pages = browser.contexts().flatMap((c) => c.pages());
    for (let i = 0; i < pages.length; i++) await pages[i].screenshot({ path: join(out, `fail-${i}.png`) });
  } catch {}
} finally {
  await browser.close();
}

