import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);

async function makePlayer(name) {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  page.on('pageerror', (e) => console.log(`[${name}] ERR ${e.message}`));
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(800);
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
  await page.locator('#heroNameInput').fill(name);
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
  await page.locator('#hud').waitFor();
  await page.waitForTimeout(900);
  if (await page.locator('[data-skip]').count()) await page.locator('[data-skip]').click();
  await page.evaluate(() => {
    window.__seen = [];
    const c = window.AETHERIA.tradeClient;
    c.on('message', (m) => window.__seen.push(m));
    const p = window.AETHERIA.game.player;
    p.inventory.push({ uid: window.__uid = 'eq_' + Math.random().toString(36).slice(2), kind: 'equip', slot: 'weapon', name: 'Test', rarity: 'epic', class: p.classId, reqLevel: 1, stats: { attack: 5 }, tradeable: true });
  });
  return page;
}
const A = await makePlayer('DbgA');
const B = await makePlayer('DbgB');
const openTrade = async (page) => {
  if (!(await page.locator('.drawer').count())) { await page.locator('[data-act="menu"]').click(); await page.locator('.drawer').waitFor(); }
  await page.locator('[data-open="trade"]').click();
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(200);
};
await openTrade(A); await openTrade(B);
await A.locator('[data-trade-connect]').click();
await B.locator('[data-trade-connect]').click();
await A.locator('.connection-status.online').waitFor();
await B.locator('.connection-status.online').waitFor();
await A.waitForTimeout(500);
console.log('ids', await A.evaluate(() => window.AETHERIA.tradeClient.identity), await B.evaluate(() => window.AETHERIA.tradeClient.identity));
await A.locator('[data-trade-invite]').first().click();
await B.locator('[data-trade-accept]').waitFor();
await B.locator('[data-trade-accept]').click();
await A.locator('[data-trade-add]').waitFor();
const add = async (page) => {
  await page.locator('[data-trade-add]').click();
  await page.locator('[data-pick-uid]').first().waitFor();
  await page.locator('[data-pick-uid]').first().click();
  await page.locator('[data-modal-close]').last().click();
  await page.waitForTimeout(400);
};
await add(A); await add(B);
await A.locator('[data-trade-ready]').click();
await B.locator('[data-trade-ready]').click();
await A.waitForTimeout(500);
console.log('A panel trade before confirm', JSON.stringify(await A.evaluate(() => {
  const panel = window.AETHERIA.panelRef;
  return { active: window.AETHERIA.tradeClient.state, seenTypes: window.__seen.map((m) => m.type) };
})));
await A.locator('[data-trade-confirm]').click();
await A.waitForTimeout(300);
await B.locator('[data-trade-confirm]').click();
await A.waitForTimeout(1200);
console.log('seen A', await A.evaluate(() => window.__seen.map((m) => m.type)));
console.log('seen B', await B.evaluate(() => window.__seen.map((m) => m.type)));
console.log('A inv', await A.evaluate(() => window.AETHERIA.game.player.inventory.map((i) => [i.uid, i.kind, i.name, i.qty])));
console.log('B inv', await B.evaluate(() => window.AETHERIA.game.player.inventory.map((i) => [i.uid, i.kind, i.name, i.qty])));
console.log('A uid', await A.evaluate(() => window.__uid));
console.log('B uid', await B.evaluate(() => window.__uid));
console.log('A complete', JSON.stringify(await A.evaluate(() => window.__seen.filter((m) => m.type === 'trade:complete'))));
console.log('panel', await A.evaluate(() => ({ tradeActive: window.AETHERIA.tradeClient.identity, players: window.AETHERIA.tradeClient.players })));
await A.screenshot({ path: '/tmp/opencode/dbg-trade.png' });
await browser.close();

