import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch(config.browser.launchOptions);
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const page = await context.newPage();
page.setDefaultTimeout(12000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('  ! ' + e.message); });
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('404') && !m.text().includes('bad HTTP')) { errors.push(m.text()); console.log('  ! ' + m.text()); } });

const step = async (name, fn) => {
  try { await fn(); console.log('OK   ' + name); }
  catch (e) { console.log('FAIL ' + name + ' :: ' + e.message); errors.push('STEP ' + name + ' ' + e.message); }
};
const state = () => page.evaluate(() => window.AETHERIA.game.player);
const openPanel = async (name) => {
  if (!(await page.locator('.drawer').count())) { await page.locator('[data-act="menu"]').click(); await page.locator('.drawer').waitFor(); }
  await page.locator(`[data-open="${name}"]`).click();
  await page.locator('.panel').waitFor();
  await page.waitForTimeout(200);
};
const closePanel = async () => {
  if (await page.locator('[data-panel-close]').count()) await page.locator('[data-panel-close]').first().click();
  await page.waitForTimeout(150);
};

try {
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(900);
  await page.locator('[data-menu-new]').click();
  await page.locator('[data-create-start]').waitFor();
  await page.locator('[data-class="assassin"]').click();
  await page.locator('#heroNameInput').fill('QuestHero');
  await page.locator('[data-create-start]').click();
  await page.locator('[data-confirm-create]').click();
  await page.locator('#hud').waitFor();
  await page.waitForTimeout(900);
  if (await page.locator('[data-skip]').count()) await page.locator('[data-skip]').click();
  await page.waitForTimeout(300);

  await step('story quest exists', async () => {
    const p = await state();
    if (!p.quests.q_green_story) throw new Error('story quest missing');
    if (p.quests.q_green_story.state !== 'active') throw new Error('not active');
  });

  await step('objective progress via real combat', async () => {
    const result = await page.evaluate(() => {
      const e = window.AETHERIA.engine;
      const p = e.player;
      const wolves = e.monsters.filter((m) => m.defId === 'wolf' && !m.dead).slice(0, 10);
      for (const m of wolves) { p.x = m.x; p.y = m.y + 8; e.hitMonster(m, 999999); }
      const elite = e.monsters.find((m) => m.elite && !m.dead);
      if (elite) { p.x = elite.x; p.y = elite.y + 8; e.hitMonster(elite, 999999); }
      const quest = p.quests.q_green_story;
      return { killed: wolves.length, progress: quest.progress, state: quest.state, elite: Boolean(elite) };
    });
    console.log('     progress:', JSON.stringify(result));
    if (result.progress[0] < 10) throw new Error('wolf objective incomplete');
    if (result.progress[1] !== 1) throw new Error('elite objective incomplete');
  });

  await step('boss objective + quest done', async () => {
    const result = await page.evaluate(() => {
      const e = window.AETHERIA.engine;
      const p = e.player;
      const boss = e.monsters.find((m) => m.boss && !m.dead);
      if (!boss) return { error: 'no boss' };
      p.x = boss.x; p.y = boss.y + 8;
      e.hitMonster(boss, 999999);
      return { boss: boss.defId, dead: boss.dead, progress: p.quests.q_green_story.progress, state: p.quests.q_green_story.state };
    });
    console.log('     boss:', JSON.stringify(result));
    if (result.state !== 'done') throw new Error('quest not done');
  });

  await step('claim story quest in UI', async () => {
    const before = await state();
    await openPanel('quests');
    await page.locator('[data-claim="q_green_story"]').waitFor();
    await page.screenshot({ path: '/tmp/opencode/quest-ready.png' });
    await page.locator('[data-claim="q_green_story"]').click();
    await page.waitForTimeout(600);
    const after = await state();
    console.log('     gold', before.gold, '->', after.gold, '| gems', before.gems, '->', after.gems, '| xp', before.xp, '->', after.xp);
    if (after.gold <= before.gold) throw new Error('gold reward missing');
    if (after.gems <= before.gems) throw new Error('gem reward missing');
    if (after.quests.q_green_story.state !== 'claimed') throw new Error('not marked claimed');
    if (!after.mounts.includes('mount_stag')) throw new Error('quest mount missing');
    if ((after.completedChapters ?? 0) < 1) throw new Error('chapter not completed');
    if (!after.discoveredZones.includes('ironcrag')) throw new Error('next zone not unlocked');
    await closePanel();
  });

  await step('side quest accept + claim', async () => {
    const p = await state();
    if (p.quests.q_green_side1) throw new Error('side quest already active');
    await openPanel('quests');
    await page.locator('[data-accept="q_green_side1"]').click();
    await page.waitForTimeout(400);
    let after = await state();
    if (!after.quests.q_green_side1) throw new Error('side quest not accepted');
    await closePanel();
    await page.evaluate(() => {
      const e = window.AETHERIA.engine; const p = e.player;
      for (let i = 0; i < 5; i++) {
        const n = e.nodes.find((x) => x.type === 'herb' && x.ready);
        n.ready = true;
        p.x = n.x; p.y = n.y + 8;
        e.updateInteraction();
        e.interact();
        e.finishGather(n);
      }
    });
    await page.waitForTimeout(400);
    after = await state();
    console.log('     side quest:', JSON.stringify(after.quests.q_green_side1));
    if (after.quests.q_green_side1.state !== 'done') throw new Error('side quest not done: ' + JSON.stringify(after.quests.q_green_side1));
    await openPanel('quests');
    await page.locator('[data-claim="q_green_side1"]').click();
    await page.waitForTimeout(400);
    after = await state();
    if (after.quests.q_green_side1.state !== 'claimed') throw new Error('side quest not claimed');
    const potions = after.inventory.find((i) => i.id === 'healPotion');
    if (!potions || potions.qty < 3) throw new Error('consumable reward missing');
    await closePanel();
  });

  await step('crit cap 50%', async () => {
    const crit = await page.evaluate(() => {
      const p = window.AETHERIA.game.player;
      p.stats.crit = 0.99;
      p.bonusCrit = 1;
      const { recalc } = window.AETHERIA;
      return p.stats.crit;
    });
    console.log('     crit stat after forcing:', crit);
    if (crit > 0.5) throw new Error('crit exceeds 50%');
  });

  await step('travel to unlocked Ironcrag', async () => {
    const ok = await page.evaluate(() => window.AETHERIA.travel('ironcrag'));
    await page.waitForTimeout(700);
    const p = await state();
    console.log('     travel:', ok, 'zone:', p.zoneId);
    if (!ok || p.zoneId !== 'ironcrag') throw new Error('travel failed');
    if (!p.quests.q_iron_story) throw new Error('next story quest missing');
  });

  await page.screenshot({ path: '/tmp/opencode/quest-final.png' });
  console.log('\nERRORS (' + errors.length + ')');
  for (const e of errors) console.log(' - ' + e);
} catch (error) {
  console.error('QUEST TEST CRASHED:', error.message);
  process.exitCode = 1;
} finally {
  await browser.close();
}

