            <div class="fr-cost"><span>${esc(t(recipe.nameKey))}</span></div>
          </div>
          <button class="btn ${can ? 'primary' : 'ghost'}" data-brew="${recipe.id}" ${can ? '' : 'disabled'}>${esc(t('smith.craftBtn'))}</button>

