      await page.waitForTimeout(200);
    };
    for (const p of ['inventory', 'quests', 'shop', 'forge', 'character', 'world', 'mounts', 'storage', 'wardrobe', 'trade']) await open(p);
  }
  await ctx.close();
}
await browser.close();
EOF
