// Copies the runtime web shell into www/ for Capacitor Android packaging.
// Usage: npm run build:web
import { cp, mkdir, readdir, rm, stat } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const out = join(root, 'www');

const ENTRIES = [
  'index.html',
  'manifest.webmanifest',
  'sw.js',
  'icons',
  'src',
];

async function main() {
  await rm(out, { recursive: true, force: true });
  await mkdir(out, { recursive: true });
  for (const entry of ENTRIES) {
    const from = join(root, entry);
    const to = join(out, entry);
    try {
      const info = await stat(from);
      if (info.isDirectory()) {
        await cp(from, to, { recursive: true });
      } else {
        await cp(from, to);
      }
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.warn(`skip missing ${entry}`);
        continue;
      }
      throw error;
    }
  }
  const files = await readdir(out);
  console.log(`Built www/ (${files.length} top-level entries) for Capacitor.`);
  console.log('Next: npx cap add android  (first time) or npm run android:sync');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

name: Android APK

on:
  workflow_dispatch:
  push:
    branches: [main]

permissions:
  contents: read

jobs:
  debug-apk:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: 21

      - name: Install dependencies
        run: npm ci

      - name: Build web shell
        run: npm run build:web

      - name: Sync Capacitor Android project
        run: npx cap sync android

      - name: Assemble debug APK
        run: |
          cd android
          chmod +x gradlew
          ./gradlew assembleDebug --no-daemon

      - name: Upload installable APK
        uses: actions/upload-artifact@v4
        with:
          name: aetheria-debug-apk
          path: android/app/build/outputs/apk/debug/app-debug.apk
          if-no-files-found: error
=== build-android
// One-command Android debug APK: web build -> Capacitor sync -> Gradle.
// Usage: npm run android:apk
//
// Requires Node 20+, an Android SDK (ANDROID_HOME) and a JDK 21 (or 17).
// The resulting APK is debug-signed and installable with `adb install`.
import { spawnSync } from 'node:child_process';
import { existsSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const isWin = process.platform === 'win32';

function run(command, args, cwd, env = {}) {
  console.log(`\n$ ${command} ${args.join(' ')}`);
  const result = spawnSync(command, args, {
    cwd,
    stdio: 'inherit',
    shell: isWin,
    env: { ...process.env, ...env },
  });
  if (result.status !== 0) {
    console.error(`\nCommand failed with exit code ${result.status ?? 'unknown'}.`);
    process.exit(result.status || 1);
  }
}

// Gradle 8/9 works with JDK 17 and 21; some newer JDKs are rejected by the
// Android Gradle plugin. Prefer an explicit JAVA_HOME, then the usual paths.
function findJavaHome() {
  if (process.env.JAVA_HOME && existsSync(process.env.JAVA_HOME)) return process.env.JAVA_HOME;
  const candidates = isWin
    ? ['C:\\Program Files\\Android\\Android Studio\\jbr']
    : [
        '/usr/lib/jvm/temurin-21-jdk-amd64',
        '/usr/lib/jvm/temurin-17-jdk-amd64',
        '/usr/lib/jvm/java-21-openjdk-amd64',
        '/usr/lib/jvm/java-17-openjdk-amd64',
        '/opt/homebrew/opt/openjdk@21',
        '/Library/Java/JavaVirtualMachines/temurin-21.jdk/Contents/Home',
      ];
  return candidates.find((path) => existsSync(path)) ?? null;
}

if (!process.env.ANDROID_HOME && !process.env.ANDROID_SDK_ROOT) {
  console.warn('Warning: ANDROID_HOME / ANDROID_SDK_ROOT is not set. Gradle may not find the SDK.');
}

const javaHome = findJavaHome();
if (!javaHome) {
  console.error('No JDK found. Set JAVA_HOME to a JDK 17 or 21 installation and retry.');
  process.exit(1);
}
console.log(`Using JAVA_HOME=${javaHome}`);

run(process.execPath, [join(root, 'tools/build-web.mjs')], root);
