    const { advanceQuests, claimQuest, saveNow } = await import('/src/core/game.js');
    const app = window.AETHERIA;
    const e = app.engine;
    const p = app.game.player;
    if (!p.quests.q_mist_story) return { error: 'story quest not active' };
    // Kill the required ten skeletons, the elite and the boss through the real kill path.
    const byId = (id) => e.monsters.filter((m) => m.defId === id && !m.dead);
    for (let i = 0; i < 10; i++) {
      const m = byId('skeleton')[i % Math.max(1, byId('skeleton').length)];
      if (!m) { advanceQuests(p, 'kill', 'skeleton', 1); continue; }
      e.killMonster(m);
    }
    const elite = byId('deathknight')[0];
    if (elite) e.killMonster(elite); else advanceQuests(p, 'killElite', 'deathknight', 1);
    const boss = e.monsters.find((m) => m.boss && !m.dead);
    e.killMonster(boss);
    const entry = p.quests.q_mist_story;
    const stateBeforeClaim = entry.state;
    const gained = claimQuest(p, 'q_mist_story');
    saveNow(true);
    return {
      stateBeforeClaim,
      gained: gained ? { wing: gained.wing, zone: gained.zone, gems: gained.gems } : null,
      wings: p.wings,
      completedChapters: p.completedChapters,
      gold: p.gold,
      bossKills: p.bossKills,
      discovered: p.discoveredZones,
    };
  });
  console.log('     ' + JSON.stringify(res));
  if (res.error) throw new Error(res.error);
  if (res.stateBeforeClaim !== 'done') throw new Error('quest not completed by kills: ' + res.stateBeforeClaim);
  if (!res.gained?.wing) throw new Error('no wing granted');
  if (!res.wings.includes('wing_eternity')) throw new Error('wing missing');
  if (res.completedChapters < 4) throw new Error('chapter not advanced');
});
await page.screenshot({ path: '/tmp/opencode/endgame.png' });

await step('wing equips and renders', async () => {
