});

await step('reload keeps level, wings, chapter and zone', async () => {
  const before = await page.evaluate(() => {
    const p = window.AETHERIA.game.player;
    return { level: p.level, wing: p.wing, wings: p.wings, ch: p.completedChapters, zone: p.zoneId };
