    return { level: p.level, wing: p.wing, wings: p.wings, ch: p.completedChapters, zone: p.zoneId };
  });
  console.log('     before=' + JSON.stringify(before) + ' after=' + JSON.stringify(after));
  if (after.level !== before.level) throw new Error('level lost');
  if (!after.wings.includes('wing_eternity')) throw new Error('wings lost');
  if (after.ch !== before.ch) throw new Error('chapter lost');
  if (after.zone !== before.zone) throw new Error('zone lost');
});

console.log('\nERRORS (' + errors.length + ')');
for (const e of errors) console.log(' - ' + e);
await browser.close();
